INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66574926', 66574926, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Penyusunan Pedoman SDGs Action Register dan Certificate pada Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGs)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 120000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pengadaan Jasa Konsultan Penyusunan Pedoman SDGs Action Register dan Certificate dilakukan dengan tujuan untuk membantu Sekretariat Nasional TPB/SDGs dalam penerapan sistem manajemen informasi dan komunikasi digital SDGs Action Register dan Certificate .', 'a. Memantau matrik RAN TPB/SDGs digital (SDGs Action Register dan Certificate ) oleh pengguna per hari, termasuk persetujuan profil, konsistens revisi pengisian matrik RAN TPB/SDGs, dan pelaporan pengkinian harian ke Sekretariat Nasional SDGs; b. Memverifikasi keakuratan pengisian matrik RAN TPB/SDGs digital (SDGs Action Register dan Certificate) oleh pengguna untuk memastikan pemrosesan dan pengisian dilakukan dengan efektif dan efisien; c. Memberikan solusi terbaik kepada pengguna berkomunikasi mengenai proses dan status rating SDGs Action Register dan Certificate serta menangani keluhan pengguna secara profesional; d. Menyusun penulisan, reviu, dasar desain Pedoman SDGs Action Register dan Certificate ; e. Bersama Tim Pilar Sosial melaksanakan Gap Analysis NSA dalam SDGs Action Register f. Bersama Tim Pilar Sosial dan Ekonomi mengembangkan SDGs Certificate berkoordinasi dengan Tim IT; g. Bersama Tim Pilar Sosial dan Ekonomi untuk membuat berbagai macam desain, khususnya pada desain komunikasi digital terkait SDGs Action Register dan Certificate berkoordinasi dengan Konsultan Komunikasi Publik; h. Melakukan pemeliharaan dan pembaharuan situs web SDGs Action Register dan Certificate berkoordinasi dengan Tim IT; i. Berkomunikasi secara intensif dengan Tim Sekretariat Nasioanl SDGs, Koordinator SDGs Action Register dan Certificate dan Tim IT untuk memastikan kelengkapan matrik SDGs Action Register dan Certificate . Menjaga komunikasi dengan pengguna jika diperlukan dokumen atau informasi tambahan; j. Membantu tim pilar pembangunan sosial dalam pelaksanaan SDGs Action Register dan Certificate. k. menginventarisasi data dukung penyusunan laporan program SDGs registrasi dan pengembangan sertifikasi aksi SDGs l. menginventarisasi data dukung penyusunan Dokumen materi dan bahan pertemuan/workshop/seminar, diseminasi dan informasi TPB/SDGs;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2852303);
