INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66584623', 66584623, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM13 KANTOR IMIGRASI KELAS I NON TPI BLORA', 'Pengadaan Jasa Konsultansi Konstruksi Perancangan Pembangunan Gedung Kantor dan Fasilitas Lainnya pada Kantor Imigrasi Kelas I Non TPI Blora - Jawa Tengah Tahun Anggaran 2026', 'Jasa Konsultansi', 'Seleksi', 'Jawa Tengah, Blora (Kab.)', 3554613000, 'March 2026', 'APBN - PNBP (D)', 0, 1, '1 PKT', 'Pengadaan Jasa Konsultan Perancangan untuk pembangunan: 1. Gedung Kantor 2. Rumah Susun 3. Kantin 4. Musholah 5. Ruang Tunggu Driver/Pengantar 6. Tempat Pembuangan Sampah 7. Pos Security 8. Power House 9. Pagar 10. Pekerjaan Sarpras berupa Pengurukan/Pematangan Lahan dan Pemasangan Paving', '1.Tahap Persiapan, paling sedikit menghasilkan: a.Program Mutu Berisikan informasi mengenai pekerjaan yang akan dilaksanakan, organisasi kerja penyedia, jadwal pelaksanaan pekerjaan, prosedur pelaksanaan pekerjaan, prosedur instruksi kerja, dan pengendalian pekerjaan. b.Laporan Hasil Kegiatan Persiapan Berisikan uraian tanggapan terhadap KAK dan rencana kerja untuk mencapai sasaran yang diharapkan dalam kontrak. 2.Tahap Pengumpulan Data dan Analisis Data, paling sedikit menghasilkan: a.Laporan Hasil Survei Berisi seluruh hasil survei, termasuk gambar sketsa, foto–foto dan data yang dihasilkan tiap-tiap survei (hasil uji lab, data sekunder dan primer). b.Analisis Data Berisi hasil analisis hasil survei (contoh: topografi, geologi dan geoteknik, hidrologi, dan lain–lain) yang kemudian dimasukkan dalam kriteria desain. c.Rencana Tindak Lanjut Berisi rencana tindak lanjut perancangan (termasuk usulan detail struktur yang akan dipilih). 3.Tahap Finalisasi Rancangan, paling sedikit menghasilkan: a.Laporan yang memuat hasil analisis data berdasarkan survei/tes dan foto dokumentasi; b.Laporan perancangan desain (perhitungan desain arsitektur, struktur serta Mechanical, Electrical and Plumbing/MEP); c.Sistem struktur yang digunakan; d.Gambar perencanaan teknis baik berupa gambar rencana dan Detail Engineering Design (DED) yang mencakup antara lain gambar arsitektur, struktur, serta MEP yang mencakup denah site plan, denah tampak, potongan, detail prinsip, dan perspektif; e. Spesifikasi teknis; f.Daftar kuantitas atau daftar keluaran (Bill of Quantity/BoQ); g.Engineer’s Estimate beserta analisanya yang telah mencakup kebutuhan biaya penerapan SMKK; h.Metode pelaksanaan; i.Penetapan tingkat kompleksitas pekerjaan; j.Kebutuhan sumber daya konstruksi (mencakup material, peralatan, dan tenaga kerja) beserta rantai pasoknya; k.Rancangan Konseptual SMKK; l.Laporan uji lab; m.Kelengkapan dokumen untuk permohonan perizinan terkait standar bangunan kepada institusi yang berwenang; n.Kelengkapan dokumen tender (antara lain gambar detail, spesifikasi teknis, BoQ); dan o.Lokasi pekerjaan.p.Perhitungan TKDNq.Rencana Penjaminan Mutu Pekerjaan Konstruksi (RPMPK)r.Rencana Keselamatan Konstruksi (RKK).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2859967);
